solution.solution.cpp:
#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <map>
#include <optional>
#include <vector>

struct Fragment
{
    std::uint16_t block;
    std::uint8_t index;
    std::uint8_t count;
    std::vector<std::uint8_t> data;
};

std::vector<Fragment> split(std::uint16_t block, const std::vector<std::uint8_t>& data, std::size_t maxFragment)
{
    if (maxFragment == 0) return {};
    const std::size_t count{ data.empty() ? 1 : (data.size() + maxFragment - 1) / maxFragment };
    if (count > 255) return {};
    std::vector<Fragment> out;
    for (std::size_t i{ 0 }; i < count; ++i)
    {
        const std::size_t begin{ std::min(i * maxFragment, data.size()) };
        const std::size_t end{ std::min(begin + maxFragment, data.size()) };
        out.push_back({ block, static_cast<std::uint8_t>(i), static_cast<std::uint8_t>(count),
                        std::vector<std::uint8_t>(data.begin() + static_cast<std::ptrdiff_t>(begin),
                                                  data.begin() + static_cast<std::ptrdiff_t>(end)) });
    }
    return out;
}

class Reassembler
{
public:
    explicit Reassembler(double timeout) : timeout_{ timeout } {}

    std::optional<std::vector<std::uint8_t>> add(const Fragment& f, double now)
    {
        expire(now);
        if (f.count == 0 || f.index >= f.count || f.data.size() > 1200) return std::nullopt;
        auto it{ blocks_.find(f.block) };
        if (it == blocks_.end())
        {
            if (blocks_.size() >= 16) return std::nullopt;
            it = blocks_.emplace(f.block, Block{ now, f.count, std::vector<std::optional<std::vector<std::uint8_t>>>(f.count), 0 }).first;
        }
        Block& b{ it->second };
        if (b.count != f.count || b.pieces[f.index]) return std::nullopt;
        b.pieces[f.index] = f.data;
        if (++b.received < b.count) return std::nullopt;
        std::vector<std::uint8_t> whole;
        for (const auto& piece : b.pieces) whole.insert(whole.end(), piece->begin(), piece->end());
        blocks_.erase(it);
        return whole;
    }

    void expire(double now)
    {
        std::erase_if(blocks_, [&](const auto& entry) { return now - entry.second.started > timeout_; });
    }

    std::size_t pending() const { return blocks_.size(); }

private:
    struct Block
    {
        double started;
        std::uint8_t count;
        std::vector<std::optional<std::vector<std::uint8_t>>> pieces;
        int received;
    };
    double timeout_;
    std::map<std::uint16_t, Block> blocks_;
};

unitTests:
using Bytes = std::vector<std::uint8_t>;
Bytes numbers(std::size_t n) { Bytes b(n); for (std::size_t i{ 0 }; i < n; ++i) b[i] = static_cast<std::uint8_t>(i * 7); return b; }
TEST("splitting") {
    const auto parts{ split(42, numbers(2500), 1000) };
    CHECK_EQ(parts.size(), 3u);
    if (parts.size() == 3) {
        CHECK_EQ(parts[0].data.size(), 1000u);
        CHECK_EQ(parts[2].data.size(), 500u);
        CHECK(parts[1].block == 42 && parts[1].index == 1 && parts[1].count == 3);
        CHECK_EQ(parts[2].data[0], static_cast<std::uint8_t>(2000 * 7));
    }
    const auto exact{ split(1, numbers(2000), 1000) };
    CHECK_EQ(exact.size(), 2u);
    const auto empty{ split(1, {}, 1000) };
    CHECK(empty.size() == 1 && empty[0].data.empty() && empty[0].count == 1);
    CHECK_EQ(split(1, numbers(2551), 10).size(), 0u);
    CHECK_EQ(split(1, numbers(2550), 10).size(), 255u);
    CHECK_EQ(split(1, numbers(5), 0).size(), 0u);
}
TEST("reassembling in any order") {
    Reassembler r{ 1.0 };
    const Bytes data{ numbers(2500) };
    const auto parts{ split(7, data, 1000) };
    CHECK(!r.add(parts[2], 0).has_value());
    CHECK(!r.add(parts[0], 0).has_value());
    CHECK_EQ(r.pending(), 1u);
    const auto whole{ r.add(parts[1], 0) };
    CHECK(whole.has_value() && *whole == data);
    CHECK_EQ(r.pending(), 0u);
    const auto single{ r.add(split(8, { 1, 2, 3 }, 1000)[0], 0) };
    CHECK(single.has_value() && *single == (Bytes{ 1, 2, 3 }));
}
TEST("two blocks at once") {
    Reassembler r{ 1.0 };
    const auto a{ split(1, numbers(30), 10) };
    const auto b{ split(2, Bytes(25, 9), 10) };
    r.add(a[0], 0); r.add(b[0], 0); r.add(b[2], 0); r.add(a[2], 0);
    CHECK_EQ(r.pending(), 2u);
    const auto gotB{ r.add(b[1], 0) };
    CHECK(gotB.has_value() && *gotB == Bytes(25, 9));
    const auto gotA{ r.add(a[1], 0) };
    CHECK(gotA.has_value() && *gotA == numbers(30));
}
TEST("bad and duplicate fragments") {
    Reassembler r{ 1.0 };
    const auto parts{ split(3, numbers(30), 10) };
    r.add(parts[0], 0);
    CHECK(!r.add(parts[0], 0).has_value());
    CHECK(!r.add(Fragment{ 3, 1, 5, { 1 } }, 0).has_value());
    CHECK(!r.add(Fragment{ 4, 0, 0, {} }, 0).has_value());
    CHECK(!r.add(Fragment{ 4, 2, 2, {} }, 0).has_value());
    CHECK(!r.add(Fragment{ 4, 0, 2, Bytes(1201, 0) }, 0).has_value());
    CHECK_EQ(r.pending(), 1u);
    r.add(parts[1], 0);
    const auto whole{ r.add(parts[2], 0) };
    CHECK(whole.has_value() && *whole == numbers(30));
}
TEST("timeouts") {
    Reassembler r{ 1.0 };
    const auto parts{ split(5, numbers(30), 10) };
    r.add(parts[0], 0);
    r.add(parts[1], 1.0);
    CHECK_EQ(r.pending(), 1u);
    CHECK(!r.add(parts[2], 1.5).has_value());
    CHECK_EQ(r.pending(), 1u);
    r.expire(2.4);
    CHECK_EQ(r.pending(), 1u);
    r.expire(2.6);
    CHECK_EQ(r.pending(), 0u);
}
TEST("a limit on blocks in progress") {
    Reassembler r{ 10.0 };
    for (std::uint16_t id{ 0 }; id < 17; ++id) r.add(split(id, numbers(20), 10)[0], 0);
    CHECK_EQ(r.pending(), 16u);
    CHECK(!r.add(split(16, numbers(20), 10)[1], 0).has_value());
    const auto done{ r.add(split(3, numbers(20), 10)[1], 0) };
    CHECK(done.has_value() && *done == numbers(20));
    CHECK_EQ(r.pending(), 15u);
}

